/**
 * A vertical sequence of dated events (`design/components/timeline.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/timeline.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  useMember,
  type Each,
  type IconProps,
  type IconRole,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/timeline.module.css'

export type TimelineTone = 'neutral' | 'accent' | 'info' | 'success' | 'warning' | 'danger'

export interface TimelineEvent {
  title: string
  time: string
  detail?: string
  icon?: IconRole
  tone?: TimelineTone
}

/** A vertical sequence of dated events: the inputs it takes, by the React member's prop names. */
export interface TimelineProps {
  /**
   * Events in reading order; Timeline never sorts them.
   */
  events: TimelineEvent[]
  /**
   * The list's accessible name, such as "Ticket history" rather than "Timeline".
   */
  label: string
}

/** A vertical sequence of dated events. */
@Component({
  selector: 'pm-timeline',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Icon],
  // prettier-ignore
  template: `@if (e1()) {<ol
[attr.class]="e2()"
[attr.aria-label]="e3()"
data-member="timeline"
>@for (event of e4(); track e5($index); let at = $index) {<!-- event -->
<li
[attr.class]="e6()"
[attr.data-tone]="e7(event)"
><!-- marker -->
<span
[attr.class]="e8()"
aria-hidden="true"
><!-- mark -->
<span
[attr.class]="e9()"
[attr.data-mark]="e10(event)"
>@if (e11(event)) {<pm-icon
[name]="e12(event)"
size="sm"
></pm-icon>}</span></span>
<!-- copy -->
<span
[attr.class]="e13()"
><!-- title -->
<span
[attr.class]="e14()"
>{{ e15(event) }}</span>
<!-- time -->
<span
[attr.class]="e16()"
>{{ e17(event) }}</span>
@if (e18(event)) {<!-- detail -->
<span
[attr.class]="e19(event)"
>{{ e20(event) }}</span>}</span></li>}</ol>}`,
})
export class Timeline {
  /**
   * Events in reading order; Timeline never sorts them.
   */
  readonly events = input.required<TimelineProps['events']>()
  /**
   * The list's accessible name, such as "Ticket history" rather than "Timeline".
   */
  readonly label = input.required<TimelineProps['label']>()
  protected readonly $ = useMember({
    events: [],
    props: { events: () => this.events(), label: () => this.label() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return this.$p.events.length > 0
  }

  protected e2() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return styles.root
  }

  protected e3() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return this.$p.label
  }

  e4() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return this.$p.events
  }

  protected e5(at: number) {
    return at
  }

  protected e6() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return styles.event
  }

  protected e7(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    return event.tone === undefined || event.tone === 'neutral' ? undefined : event.tone
  }

  protected e8() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return styles.marker
  }

  protected e9() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return styles.mark
  }

  protected e10(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    return event.icon === undefined ? 'dot' : 'icon'
  }

  protected e11(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    return event.icon !== undefined
  }

  protected e12(event: Each<ReturnType<Timeline['e4']>>): IconProps['name'] {
    if (!(this.$p.events.length > 0)) return undefined as never
    if (!(event.icon !== undefined)) return undefined as never
    return event.icon
  }

  protected e13() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return styles.copy
  }

  protected e14() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return styles.title
  }

  protected e15(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    return event.title
  }

  protected e16() {
    if (!(this.$p.events.length > 0)) return undefined as never
    return styles.time
  }

  protected e17(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    return event.time
  }

  protected e18(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    return event.detail !== undefined
  }

  protected e19(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    if (!(event.detail !== undefined)) return undefined as never
    return styles.detail
  }

  protected e20(event: Each<ReturnType<Timeline['e4']>>) {
    if (!(this.$p.events.length > 0)) return undefined as never
    if (!(event.detail !== undefined)) return undefined as never
    return event.detail
  }
}
